let LANG = 'de';
try { LANG = localStorage.getItem('lang') || (navigator.language || 'de').slice(0, 2); } catch {}
if (!I18N[LANG]) LANG = 'de';

function t(key, vars) {
  let s = I18N[LANG][key] ?? I18N.de[key] ?? key;
  if (vars) for (const [k, v] of Object.entries(vars)) s = s.replace('{' + k + '}', v);
  return s;
}
// Picks the current language from a {de, ru, en} object; plain strings pass through.
function tr(v) { return v && typeof v === 'object' ? (v[LANG] ?? v.de ?? v.ru ?? '') : (v ?? ''); }

function applyI18n() {
  document.documentElement.lang = LANG;
  document.querySelectorAll('[data-i18n]').forEach(el => { el.textContent = t(el.dataset.i18n); });
  document.querySelectorAll('[data-i18n-ph]').forEach(el => { el.placeholder = t(el.dataset.i18nPh); });
  document.querySelectorAll('[data-i18n-title]').forEach(el => { el.title = t(el.dataset.i18nTitle); });
}
function setLang(l) {
  if (!I18N[l]) return;
  LANG = l;
  try { localStorage.setItem('lang', l); } catch {}
  applyI18n();
}
